<?php declare(strict_types=1);require_once __DIR__.'/_common.php';$eventId=(int)($_GET['event_id']??$_POST['event_id']??0);if(post()){verifyCsrf();$action=$_POST['action']??'';$member=(int)($_POST['member_id']??0);if($action==='assign'&&$eventId&&$member){db()->prepare('INSERT IGNORE INTO event_members(event_id,member_id,assigned_by) VALUES(?,?,?)')->execute([$eventId,$member,$admin['id']]);flash('success','Member assigned.');}elseif($action==='remove'&&$member){db()->prepare('DELETE FROM event_members WHERE event_id=? AND member_id=?')->execute([$eventId,$member]);flash('success','Member removed.');}redirect('event-members.php?event_id='.$eventId);}$s=db()->prepare('SELECT * FROM events WHERE id=?');$s->execute([$eventId]);$event=$s->fetch();if(!$event){http_response_code(404);exit('Event not found.');}$members=db()->query("SELECT id,full_name,email FROM users WHERE role='member' AND is_active=1 AND is_banned=0 ORDER BY full_name")->fetchAll();$s=db()->prepare('SELECT em.member_id,u.full_name,u.email FROM event_members em JOIN users u ON u.id=em.member_id WHERE em.event_id=? ORDER BY u.full_name');$s->execute([$eventId]);$assigned=$s->fetchAll();$pageTitle='Event members';require dirname(__DIR__).'/includes/header.php';?><section class="section"><div class="container"><p class="eyebrow">Event management</p><h1 class="section-title">Assign members.</h1><p class="copy">Event: <?=e($event['title_en'])?> · <?=e($event['event_date'])?></p><div class="form-shell" style="max-width:none"><form method="post"><?=csrfField()?><input type="hidden" name="action" value="assign"><input type="hidden" name="event_id" value="<?=$eventId?>"><div class="field"><label>Member</label><select name="member_id" required><option value="">Choose member</option><?php foreach($members as $m):?><option value="<?=$m['id']?>"><?=e($m['full_name'])?> · <?=e($m['email'])?></option><?php endforeach;?></select></div><button class="btn primary">Assign member</button></form></div><div class="table-wrap"><table><thead><tr><th>Member</th><th>Email</th><th>Action</th></tr></thead><tbody><?php foreach($assigned as $m):?><tr><td><?=e($m['full_name'])?></td><td><?=e($m['email'])?></td><td><form method="post"><?=csrfField()?><input type="hidden" name="action" value="remove"><input type="hidden" name="event_id" value="<?=$eventId?>"><input type="hidden" name="member_id" value="<?=$m['member_id']?>"><button class="btn coral">Remove</button></form></td></tr><?php endforeach;?></tbody></table></div></div></section><?php require dirname(__DIR__).'/includes/footer.php';
